export function useAnswer(jobId: string, fieldId: string) {
  const answer = useObservable(() => answers.observeOne(jobId, fieldId), [jobId, fieldId]);

  const save = useMemo(() => debounce(async (value: string) => {
    await database.write(async () => {
      await answerRepo.upsert(jobId, fieldId, value);                     // the row
      await outboxRepo.add({ entity: 'answer', entityId: jobId + ':' + fieldId,
                             op: 'upsert', payload: { value } });        // the intent
    });
    SyncModule.requestSync('user_edit');                                   // native, returns at once
  }, 400), [jobId, fieldId]);

  return { value: answer ? answer.value : '', syncState: answer ? answer.syncState : 'synced', save };
}

fun capture(jobId: String) {
  val file = File(context.filesDir, "media/" + UUID.randomUUID() + ".jpg")
  val options = ImageCapture.OutputFileOptions.Builder(file).build()
  imageCapture.takePicture(options, cameraExecutor, object : ImageCapture.OnImageSavedCallback {
    override fun onImageSaved(result: ImageCapture.OutputFileResults) {
      scope.launch(Dispatchers.IO) {
        val sha = sha256(file)                                    // evidence hash at capture time
        repo.attachMedia(jobId, file.path, sha, bootTimeMs = SystemClock.elapsedRealtime())
        transfers.enqueue(file, owner = jobId, priority = Priority.BACKGROUND)
        events.emit(CameraEvent.Saved(thumbnailFor(file)))       // JS gets a small thumbnail path
      }
    }
    override fun onError(e: ImageCaptureException) { events.tryEmit(CameraEvent.Failed(e.message)) }
  })
}

class ConnectionManager(private val client: OkHttpClient, private val repo: MessageRepo) {
  private var socket: WebSocket? = null
  private var attempt = 0
  val state = MutableStateFlow(ConnState.CONNECTING)

  fun connect(token: String) {
    val req = Request.Builder().url(WS_URL).header("Authorization", "Bearer " + token).build()
    socket = client.newWebSocket(req, object : WebSocketListener() {
      override fun onOpen(ws: WebSocket, r: Response) {
        attempt = 0; state.value = ConnState.ONLINE
        scope.launch { repo.pending().forEach { ws.send(it.toSendFrame()) } }      // same client_msg_id
      }
      override fun onMessage(ws: WebSocket, text: String) { scope.launch { repo.applyFrame(Frame.parse(text)) } }
      override fun onFailure(ws: WebSocket, t: Throwable, r: Response?) { retry(token) }
      override fun onClosed(ws: WebSocket, code: Int, reason: String) { retry(token) }
    })
  }

  private fun retry(token: String) {
    state.value = ConnState.RECONNECTING
    val delayMs = Random.nextLong(0, min(30_000L, 1_000L shl min(attempt++, 5)))   // full jitter
    scope.launch { delay(delayMs); connect(token) }
  }
}

