@OptIn(ExperimentalPagingApi::class)
class FeedMediator(private val api: FeedApi, private val db: AppDb) : RemoteMediator<Int, PostEntity>() {
  override suspend fun load(type: LoadType, state: PagingState<Int, PostEntity>): MediatorResult {
    val cursor = when (type) {
      LoadType.REFRESH -> null
      LoadType.PREPEND -> return MediatorResult.Success(endOfPaginationReached = true)
      LoadType.APPEND -> db.feedMeta().nextCursor() ?: return MediatorResult.Success(true)
    }
    return try {
      val page = api.feed(cursor, limit = 20)
      db.withTransaction {
        if (type == LoadType.REFRESH) db.posts().clearFeed()
        db.posts().insertAll(page.items.map { it.toEntity() })
        db.feedMeta().setNextCursor(page.nextCursor)
      }
      MediatorResult.Success(endOfPaginationReached = page.nextCursor == null)
    } catch (e: IOException) { MediatorResult.Error(e) }
  }
}

export function Feed({ posts }: { posts: Post[] }) {
  const [activeId, setActiveId] = useState<string | null>(null);
  const onViewable = useRef(({ viewableItems }: any) => {
    const v = viewableItems.find((i: any) => i.item.kind === 'video' && i.isViewable);
    setActiveId(v ? v.item.id : null);                     // only the fully visible video plays
  }).current;

  return (
    <FlashList
      data={posts}
      keyExtractor={p => p.id}
      getItemType={p => p.kind}                             // separate recycling pools
      estimatedItemSize={420}
      onViewableItemsChanged={onViewable}
      viewabilityConfig={{ itemVisiblePercentThreshold: 80 }}
      renderItem={({ item }) => <PostCard post={item} playing={item.id === activeId} />}
    />
  );
}

sealed interface CheckoutUi {
  data object Ready : CheckoutUi
  data object Submitting : CheckoutUi
  data class Confirming(val orderId: String) : CheckoutUi
  data class Paid(val orderId: String) : CheckoutUi
  data class Failed(val reason: String) : CheckoutUi
}

class CheckoutViewModel(private val saved: SavedStateHandle, private val api: OrderApi) : ViewModel() {
  private val idemKey: String = saved["idemKey"] ?: UUID.randomUUID().toString().also { saved["idemKey"] = it }
  val ui = MutableStateFlow<CheckoutUi>(saved.get<String>("orderId")?.let { CheckoutUi.Confirming(it) } ?: CheckoutUi.Ready)

  fun pay(cart: Cart, method: MethodToken) {
    if (ui.value !is CheckoutUi.Ready) return                       // no second submit
    ui.value = CheckoutUi.Submitting
    viewModelScope.launch {
      val order = api.createOrder(cart, method, idempotencyKey = idemKey)   // same key on every retry
      saved["orderId"] = order.id
      ui.value = CheckoutUi.Confirming(order.id)
      pollUntilFinal(order.id)
    }
  }

  private suspend fun pollUntilFinal(id: String) {
    var wait = 1_000L
    repeat(12) {
      when (val s = api.order(id).state) {
        "paid" -> { ui.value = CheckoutUi.Paid(id); return }
        "failed" -> { ui.value = CheckoutUi.Failed(api.order(id).reason); return }
      }
      delay(wait); wait = min(wait * 2, 15_000L)
    }                                                                  // stays Confirming; push will update
  }
}

function HoldTimer({ expiresAt, serverOffsetMs, onExpire }: Props) {
  const [left, setLeft] = useState(() => expiresAt - (Date.now() + serverOffsetMs));
  useEffect(() => {
    const t = setInterval(() => {
      const ms = expiresAt - (Date.now() + serverOffsetMs);   // server time, not the phone's clock
      setLeft(ms);
      if (ms <= 0) { clearInterval(t); onExpire(); }
    }, 1000);
    return () => clearInterval(t);
  }, [expiresAt, serverOffsetMs]);
  const s = Math.max(0, Math.round(left / 1000));
  return <Text accessibilityLiveRegion="polite">Held for {Math.floor(s / 60)}:{String(s % 60).padStart(2, '0')}</Text>;
}

