fun stream(req: Request): Flow<AssistantEvent> = callbackFlow {
  val source = EventSources.createFactory(client).newEventSource(req, object : EventSourceListener() {
    override fun onEvent(es: EventSource, id: String?, type: String?, data: String) {
      trySend(when (type) {
        "token" -> AssistantEvent.Token(json.decode<TokenData>(data).t)
        "tool" -> AssistantEvent.Tool(json.decode<ToolData>(data).label)
        "card" -> AssistantEvent.Card(json.decode<ActionCard>(data))
        "done" -> AssistantEvent.Done(json.decode<Usage>(data))
        else -> AssistantEvent.Ignored
      })
    }
    override fun onFailure(es: EventSource, t: Throwable?, r: Response?) { close(t ?: IOException("stream failed")) }
    override fun onClosed(es: EventSource) { close() }
  })
  awaitClose { source.cancel() }                         // Stop button cancels the collector
}

