// Shared code sees one interface. Android backs it with Gemini Nano (AICore) and iOS with
// Apple's Foundation Models framework, each in its own platform source set.
enum class Availability { READY, DOWNLOADING, UNSUPPORTED }

interface OnDeviceModel {
  suspend fun availability(): Availability
  suspend fun generate(instructions: String, input: String): String
}

class Summariser(private val local: OnDeviceModel, private val cloudOrFallback: suspend (String) -> AiResult<String>) {
  suspend fun summarise(text: String): AiResult<String> {
    if (local.availability() != Availability.READY) return cloudOrFallback(text)   // older device or model not ready
    return try {
      val out = local.generate("Summarise service descriptions in 60 words or fewer.", text)
      AiResult.Ok(out, Source.SYSTEM_MODEL)
    } catch (e: CancellationException) {
      throw e                                          // never swallow cancellation
    } catch (e: Exception) {
      cloudOrFallback(text)
    }
  }
}

suspend fun summarise(text: String): AiResult<String> {
  val rule = remoteRules.summarise
  if (capabilities.hasSystemModel && capabilities.ramGb >= rule.minRamGbLocal) {
    withTimeoutOrNull(rule.localTimeoutMs) { local.summarise(text) }?.let { return AiResult.Ok(it, Source.SYSTEM_MODEL) }
  }
  if (network.isOnline) return runCatching { cloud.summarise(text) }
    .map { AiResult.Ok(it, Source.CLOUD) }
    .getOrElse { fallback(text) }
  return fallback(text)                                          // first two sentences, never an error
}

private fun fallback(text: String) = AiResult.Fallback(text.split(". ").take(2).joinToString(". ") + ".", "offline")

export function Answer({ text, citations }: { text: string; citations: Record<string, Citation> }) {
  const parts = text.split(/(\[\d+\])/g);                  // keep [1], [2] as separate parts
  return (
    <p className="answer">
      {parts.map((part, i) => {
        const m = part.match(/^\[(\d+)\]$/);
        if (!m) return <span key={i}>{part}</span>;
        const c = citations[m[1]];
        if (!c) return null;                                   // never show a citation we can't back
        return (
          <SourcePopover key={i} citation={c}>
            <button className="cite" aria-label={'Source ' + m[1] + ': ' + c.title}>{m[1]}</button>
          </SourcePopover>
        );
      })}
    </p>
  );
}

