export async function* streamChat(req: ChatRequest, opts: { signal?: AbortSignal; maxRetries?: number } = {}) {
  for (let attempt = 0; ; attempt++) {
    const res = await fetch(GATEWAY + '/v1/chat', { method: 'POST', body: JSON.stringify({ ...req, stream: true }), signal: opts.signal });
    if ((res.status === 429 || res.status === 503) && attempt < (opts.maxRetries ?? 2)) {
      const wait = Number(res.headers.get('Retry-After') ?? 1) * 1000;
      await sleep(wait * (0.5 + Math.random()));                // jittered, server-paced
      continue;
    }
    if (!res.ok) throw new LlmError(res.status, await res.text());
    yield* parseSse(res.body!);                                   // tokens, then a usage event
    return;
  }
}

function useFleetMetrics(model: string) {
  const [points, setPoints] = useState<MetricPoint[]>([]);
  useEffect(() => {
    const es = new EventSource('/ops/metrics?model=' + encodeURIComponent(model));
    es.onmessage = e => setPoints(p => [...p.slice(-299), JSON.parse(e.data)]);   // keep last 300 points
    return () => es.close();
  }, [model]);
  return points;
}

export function LabelView({ item, onLabel }: { item: ReviewItem; onLabel: (l: Label) => void }) {
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLTextAreaElement) return;            // don't hijack typing
      const map: Record<string, Label> = { '1': 'good', '2': 'minor_issue', '3': 'wrong', '4': 'unsafe' };
      if (map[e.key]) { e.preventDefault(); onLabel(map[e.key]); }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [item.id, onLabel]);

  return (
    <div className="label-view">
      <Context text={item.context} highlights={item.groundedSpans} />
      <Output text={item.output} />
      <Rubric hints={['1 good', '2 minor issue', '3 wrong', '4 unsafe']} />
    </div>
  );
}

